import{_ as a,o as n,c as e,S as p}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse('{"title":"Archlinux折腾笔记","description":"","frontmatter":{"layout":"post","title":"Archlinux折腾笔记","date":"2014-04-20 19:52","comments":true,"archives":2014,"tags":["notes","linux"]},"headers":[],"relativePath":"posts/2014-04-20-linux-notes/index.md","filePath":"posts/2014/2014-04-20-linux-notes.md"}'),o={name:"posts/2014-04-20-linux-notes/index.md"};function l(r,s,t,i,c,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>四月也算过去了一大半了,经过了一个月的奔波与折腾,总算安顿好自己了.在学校本地找了一个还算不错的实习. 阴差阳错的选择了 Web 开发工程师的职位,其实我最想做的是后端开发,前端也还是比较喜欢的.但是我有个很大的 缺点就是不会设计... 不会设计的前端开发工程师很鸡肋的,每次网站开发都是同学出设计图我来做的.这样不行的, 我必须能独当一面才算能在公司站得住脚.</p><p>近况就是这些,接下来就是记录下自己在 Archlinux 下折腾的东西.方便自己以后查询使用.</p><h2 id="linux-下视频截图制作动态-gif" tabindex="-1">Linux 下视频截图制作动态 GIF <a class="header-anchor" href="#linux-下视频截图制作动态-gif" aria-label="Permalink to &quot;Linux 下视频截图制作动态 GIF&quot;">​</a></h2><p>观看视频遇到经典的镜头当然得录下来做成 GIF~ 首先需要安装 <code>imagemagick</code> 这个软件包才行</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">mplayer</span><span style="color:#005CC5;"> -vo</span><span style="color:#032F62;"> png</span><span style="color:#005CC5;"> -ss</span><span style="color:#032F62;"> 00:08:28</span><span style="color:#005CC5;"> -frames</span><span style="color:#005CC5;"> 200</span><span style="color:#032F62;"> 123.mp4</span></span>
<span class="line"><span style="color:#6F42C1;">mogrify</span><span style="color:#005CC5;"> -resize</span><span style="color:#032F62;"> 848x480</span><span style="color:#005CC5;"> *</span><span style="color:#032F62;">.png</span></span>
<span class="line"><span style="color:#6F42C1;">convert</span><span style="color:#005CC5;"> -delay</span><span style="color:#005CC5;"> 4</span><span style="color:#005CC5;">  *</span><span style="color:#032F62;">.png</span><span style="color:#032F62;"> ry.gif</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>第一句话是利用 mplayer 输出 png 格式图片,从 8 分 28 秒开始,截图 200 帧,也可以换成</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">mplayer</span><span style="color:#005CC5;"> -vo</span><span style="color:#032F62;"> png:z=</span><span style="color:#005CC5;">1</span><span style="color:#005CC5;"> -ss</span><span style="color:#032F62;"> 00:08:28</span><span style="color:#005CC5;"> -endpos</span><span style="color:#005CC5;"> 8</span><span style="color:#032F62;">  123.mp4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样就是截取 8 秒,png 后面的 z=1 是压缩比例从 0 到 9 压缩程度递增,压缩速度也递增. 第二行便是修改尺寸,毕竟 720p 的 GIF 实在是吃不消啊.然后第三行变把这些 png 生成 GIF 了.</p><h2 id="sudo-设置环境变量" tabindex="-1">sudo 设置环境变量 <a class="header-anchor" href="#sudo-设置环境变量" aria-label="Permalink to &quot;sudo 设置环境变量&quot;">​</a></h2><p>有时候程序需要使用 root 权限,但当我使用 sudo 的时候结果发现这时候程序又使用 root 用户的配置文件了.<br> 现在的需求就是程序使用 root 权限运行但是执行时候读取 HOME 变量还是当前用户.<br><a href="https://wiki.archlinux.org/index.php/Sudo#Run_X11_apps_using_sudo" target="_blank" rel="noreferrer">Run_X11_apps_using_sudo</a> wiki 上有清楚的讲解这样的解决办法.</p>`,10)])])}const C=a(o,[["render",l]]);export{y as __pageData,C as default};
